use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Bootstrap5Executor { pub fn new () -> Self { Self { audit_log : Vec :: new () , } } # [doc = " Execute a big function and trace all its calls"] pub fn execute_with_call_tracing (& mut self , crate_path : & Path) -> Result < () > { self . log ("🚀 Starting call tracing execution") ; unsafe { CALL_STACK . clear () ; CALL_TREE . clear () ; CALL_COUNTER = 0 ; } self . log ("📋 Executing traced_setup_crate_paths") ; let _paths = traced_setup_crate_paths (crate_path) ? ; self . log ("📋 Executing multiple traced functions") ; for i in 1 ..= 3 { let _paths = trace_call ! (& format ! ("setup_crate_paths_call_{}" , i) , setup_crate_paths (crate_path)) ? ; } self . show_call_tree () ; Ok (()) } fn show_call_tree (& mut self) { self . log ("🌳 CALL TREE ANALYSIS:") ; unsafe { for trace in & CALL_TREE { let indent = "  " . repeat (trace . depth) ; let parent_info = match trace . parent_id { Some (pid) => format ! (" (parent: {})" , pid) , None => " (root)" . to_string () , } ; self . log (& format ! ("{}├─ {} (ID: {}{}) - {}ms - {}" , indent , trace . function_name , trace . call_id , parent_info , trace . duration_ms , if trace . success { "✅" } else { "❌" })) ; } let total_calls = CALL_TREE . len () ; let total_duration : u128 = CALL_TREE . iter () . map (| t | t . duration_ms) . sum () ; let max_depth = CALL_TREE . iter () . map (| t | t . depth) . max () . unwrap_or (0) ; self . log (& format ! ("📊 CALL STATISTICS:")) ; self . log (& format ! ("  Total calls: {}" , total_calls)) ; self . log (& format ! ("  Total duration: {}ms" , total_duration)) ; self . log (& format ! ("  Max call depth: {}" , max_depth)) ; } } fn log (& mut self , message : & str) { println ! ("[BOOTSTRAP5] {}" , message) ; self . audit_log . push (message . to_string ()) ; } pub fn get_audit_log (& self) -> & [String] { & self . audit_log } }